        _get_feeding_history_tool(),
        _get_current_diet_tool(),
        _add_medical_record_tool(),
        _get_medical_records_tool(),
        _add_measurement_tool(),
        _get_measurements_tool(),
        _add_vet_visit_tool(),
        _get_vet_visits_tool(),
